    93→FString FWjWorldWallLayoutConverter::WallLayoutToCSVString(const TArray<TArray<int32>>& WallLayout)
    94→{
    95→	FString Result;
    96→
    97→	for (int32 Row = 0; Row < WallLayout.Num(); ++Row)
    98→	{
    99→		const TArray<int32>& RowData = WallLayout[Row];
   100→		for (int32 Col = 0; Col < RowData.Num(); ++Col)
   101→		{
   102→			Result += FString::Printf(TEXT("%d"), RowData[Col]);
   103→			if (Col < RowData.Num() - 1)
   104→			{
   105→				Result += TEXT(",");
   106→			}
   107→		}
   108→		Result += TEXT("\n");
   109→	}
   110→
   111→	return Result;
   112→}
