   170→void FWjWorldWallLayoutConverter::MarkExteriorCells(
   171→	const TArray<TArray<int32>>& WallLayout,
   172→	TSet<FIntPoint>& OutExteriorCells)
   173→{
   174→	OutExteriorCells.Empty();
   175→
   176→	const int32 Rows = WallLayout.Num();
   177→	if (Rows == 0) return;
   178→
   179→	const int32 Cols = WallLayout[0].Num();
   180→	if (Cols == 0) return;
   181→
   182→	const TArray<FIntPoint> Directions = {
   183→		{ 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 },
   184→		{ 1, 1 }, { -1, 1 }, { 1, -1 }, { -1, -1 }
   185→	};
   186→
   187→	TQueue<FIntPoint> Queue;
   188→
   189→	// 경계(가장자리)에 있는 모든 빈 셀을 시작점으로 추가
   190→	// 상단/하단 행
   191→	for (int32 X = 0; X < Cols; ++X)
   192→	{
   193→		if (WallLayout[0][X] == WallCell_Empty)
   194→		{
   195→			FIntPoint Pt(X, 0);
   196→			if (!OutExteriorCells.Contains(Pt))
   197→			{
   198→				OutExteriorCells.Add(Pt);
   199→				Queue.Enqueue(Pt);
   200→			}
   201→		}
   202→		if (WallLayout[Rows - 1][X] == WallCell_Empty)
   203→		{
   204→			FIntPoint Pt(X, Rows - 1);
   205→			if (!OutExteriorCells.Contains(Pt))
   206→			{
   207→				OutExteriorCells.Add(Pt);
   208→				Queue.Enqueue(Pt);
   209→			}
   210→		}
   211→	}
   212→
   213→	// 좌측/우측 열
   214→	for (int32 Y = 0; Y < Rows; ++Y)
   215→	{
   216→		if (WallLayout[Y][0] == WallCell_Empty)
   217→		{
   218→			FIntPoint Pt(0, Y);
   219→			if (!OutExteriorCells.Contains(Pt))
   220→			{
   221→				OutExteriorCells.Add(Pt);
   222→				Queue.Enqueue(Pt);
   223→			}
   224→		}
   225→		if (WallLayout[Y][Cols - 1] == WallCell_Empty)
   226→		{
   227→			FIntPoint Pt(Cols - 1, Y);
   228→			if (!OutExteriorCells.Contains(Pt))
   229→			{
   230→				OutExteriorCells.Add(Pt);
   231→				Queue.Enqueue(Pt);
   232→			}
   233→		}
   234→	}
   235→
   236→	// Flood Fill: 경계에서 연결된 모든 빈 셀을 외부로 마킹
   237→	while (!Queue.IsEmpty())
   238→	{
   239→		FIntPoint Current;
   240→		Queue.Dequeue(Current);
   241→
   242→		for (const FIntPoint& Dir : Directions)
   243→		{
   244→			const int32 NX = Current.X + Dir.X;
   245→			const int32 NY = Current.Y + Dir.Y;
   246→
   247→			// 범위 체크
   248→			if (NX < 0 || NX >= Cols || NY < 0 || NY >= Rows)
   249→				continue;
   250→
   251→			// 벽이면 통과 불가
   252→			if (WallLayout[NY][NX] >= WallCell_Wall)
   253→				continue;
   254→
   255→			FIntPoint Next(NX, NY);
   256→			if (!OutExteriorCells.Contains(Next))
   257→			{
   258→				OutExteriorCells.Add(Next);
   259→				Queue.Enqueue(Next);
   260→			}
   261→		}
   262→	}
   263→}
   264→
   265→bool FWjWorldWallLayoutConverter::FindInteriorEmptyCell(
   266→	const TArray<TArray<int32>>& WallLayout,
   267→	const TSet<FIntPoint>& ExteriorCells,
   268→	int32& OutX,
   269→	int32& OutY)
   270→{
   271→	for (int32 Y = 0; Y < WallLayout.Num(); ++Y)
   272→	{
   273→		for (int32 X = 0; X < WallLayout[Y].Num(); ++X)
   274→		{
   275→			// 빈 셀이면서 외부 영역이 아닌 경우 = 내부 영역
   276→			if (WallLayout[Y][X] == WallCell_Empty && !ExteriorCells.Contains(FIntPoint(X, Y)))
   277→			{
   278→				OutX = X;
   279→				OutY = Y;
   280→				return true;
   281→			}
   282→		}
   283→	}
   284→
   285→	return false;
   286→}
