    73→void FWjWorldWallDescription::GetRandomSafeZones(TArray<FIntPoint>& OutSafeZones, int32 MaxCount) const
    74→{
    75→    OutSafeZones.Reset();
    76→
    77→    if (SafeZones.Num() == 0 || MaxCount <= 0)
    78→    {
    79→        return;
    80→    }
    81→
    82→    // 원본 보호용 복사
    83→    TArray<FIntPoint> ShuffledZones = SafeZones;
    84→
    85→    // 랜덤 셔플
    86→    for (int32 i = ShuffledZones.Num() - 1; i > 0; --i)
    87→    {
    88→        const int32 RandIndex = FMath::RandRange(0, i);
    89→        ShuffledZones.Swap(i, RandIndex);
    90→    }
    91→
    92→    const int32 CountToTake = FMath::Min(MaxCount, ShuffledZones.Num());
    93→
    94→    for (int32 i = 0; i < CountToTake; ++i)
    95→    {
    96→        OutSafeZones.Add(ShuffledZones[i]);
    97→    }
    98→}
