   100→bool FWjWorldWallDescription::ParseWallLayout(const FString& FileContent)
   101→{
   102→    TArray<FString> Lines;
   103→    FileContent.ParseIntoArrayLines(Lines);
   104→
   105→	int32 BeforeColumnNum = -1;
   106→
   107→    for (const FString& Line : Lines)
   108→    {
   109→        if (Line.IsEmpty())
   110→            continue;
   111→
   112→        // 메타데이터 라인 파싱 (#META:Key:Value)
   113→        if (Line.StartsWith(TEXT("#")))
   114→        {
   115→            if (Line.StartsWith(TEXT("#META:CenterOffset:")))
   116→            {
   117→                FString OffsetStr = Line.RightChop(19); // "#META:CenterOffset:" 길이 = 19
   118→                TArray<FString> Components;
   119→                OffsetStr.ParseIntoArray(Components, TEXT(","));
   120→                if (Components.Num() == 3)
   121→                {
   122→                    CenterOffset.X = FCString::Atof(*Components[0]);
   123→                    CenterOffset.Y = FCString::Atof(*Components[1]);
   124→                    CenterOffset.Z = FCString::Atof(*Components[2]);
   125→                    UE_LOG(LogWjWorld, Log, TEXT("Wall layout CenterOffset parsed: (%f, %f, %f)"),
   126→                        CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   127→                }
   128→            }
   129→            continue;
   130→        }
   131→
   132→        TArray<FString> Values;
   133→        Line.ParseIntoArray(Values, TEXT(","), true);
   134→
   135→        TArray<int32> Row;
   136→        for (const FString& Value : Values)
   137→        {
   138→            Row.Add(FCString::Atoi(*Value));
   139→        }
   140→
   141→        if (BeforeColumnNum == -1)
   142→        {
   143→            BeforeColumnNum = Row.Num();
   144→			ColumnNum = BeforeColumnNum;
   145→        }
   146→        else if (BeforeColumnNum != Row.Num())
   147→        {
   148→            UE_LOG(LogWjWorld, Error, TEXT("Inconsistent column count in wall layout file. Expected: %d, Found: %d"), BeforeColumnNum, Row.Num());
   149→            bSizeExactMatch = false;
   150→            return false;
   151→        }
   152→
   153→        WallLayout.Add(Row);
   154→    }
   155→
   156→    RowNum = WallLayout.Num();
   157→    bSizeExactMatch = true;
   158→
   159→    UE_LOG(LogWjWorld, Log, TEXT("Wall layout loaded: %d rows, %d columns"), RowNum, ColumnNum);
   160→    return true;
   161→}
