   221→            {
   222→                OutExteriorCells.Add(Pt);
   223→                Queue.Enqueue(Pt);
   224→            }
   225→        }
   226→    }
   227→
   228→    // 좌측/우측 열
   229→    for (int32 Y = 0; Y < Rows; ++Y)
   230→    {
   231→        if (WallLayout[Y][0] == WallCell_Empty)
   232→        {
   233→            FIntPoint Pt(0, Y);
