   251→    // Flood Fill: 경계에서 연결된 모든 빈 셀을 외부로 마킹
   252→    while (!Queue.IsEmpty())
   253→    {
   254→        FIntPoint Current;
   255→        Queue.Dequeue(Current);
   256→
   257→        for (const FIntPoint& Dir : Directions)
   258→        {
   259→            const int32 NX = Current.X + Dir.X;
   260→            const int32 NY = Current.Y + Dir.Y;
   261→
   262→            // 범위 체크
   263→            if (NX < 0 || NX >= Cols || NY < 0 || NY >= Rows)
   264→                continue;
   265→
   266→            // 벽이면 통과 불가
   267→            if (WallLayout[NY][NX] >= 1)
   268→                continue;
   269→
   270→            FIntPoint Next(NX, NY);
   271→            if (!OutExteriorCells.Contains(Next))
   272→            {
   273→                OutExteriorCells.Add(Next);
   274→                Queue.Enqueue(Next);
   275→            }
   276→        }
   277→    }
   278→}
