   280→bool FWjWorldWallDescription::IsAreaEnclosedByWalls(int32 StartX, int32 StartY)
   281→{
   282→    const int32 Rows = WallLayout.Num();
   283→    if (Rows == 0) return false;
   284→
   285→    const int32 Cols = WallLayout[0].Num();
   286→
   287→    // 시작 위치 유효성
   288→    if (StartX < 0 || StartX >= Cols || StartY < 0 || StartY >= Rows)
   289→        return false;
   290→
   291→    // 시작 지점이 벽이면 검사 불필요
   292→    if (WallLayout[StartY][StartX] >= 1)
   293→        return true;
   294→
   295→    TQueue<FIntPoint> Queue;
   296→    TSet<FIntPoint> Visited;
   297→
   298→    Queue.Enqueue(FIntPoint(StartX, StartY));
   299→    Visited.Add(FIntPoint(StartX, StartY));
   300→
   301→    const TArray<FIntPoint> Directions = {
   302→        { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 },
   303→        { 1, 1 }, { -1, 1 }, { 1, -1 }, { -1, -1 }
   304→    };
   305→
   306→    while (!Queue.IsEmpty())
   307→    {
   308→        FIntPoint Current;
   309→        Queue.Dequeue(Current);
   310→
   311→        for (const FIntPoint& Dir : Directions)
   312→        {
   313→            const int32 NX = Current.X + Dir.X;
   314→            const int32 NY = Current.Y + Dir.Y;
   315→
   316→            if (NX < 0 || NX >= Cols || NY < 0 || NY >= Rows)
   317→            {
   318→                return false;
   319→            }
   320→
   321→            // 벽(1 이상)이면 통과 불가
   322→            if (WallLayout[NY][NX] >= 1)
   323→                continue;
   324→
   325→            FIntPoint Next(NX, NY);
   326→            if (!Visited.Contains(Next))
   327→            {
   328→                Visited.Add(Next);
   329→                Queue.Enqueue(Next);
   330→            }
   331→        }
   332→    }
   333→
   334→    SafeZones.Empty();
   335→    SafeZones.Append(Visited.Array());
   336→
   337→    SafeZonesSet = Visited;
   338→
   339→    // 끝까지 못 나갔으면 완전히 둘러싸임
   340→    return true;
   341→}
