   181→FVector UWjWorldBrickMovement::GetMovementVector(bool bIsNew)
   182→{
   183→	if (!BrickComponent.IsValid()) return FVector();
   184→	
   185→	if (bIsNew)
   186→	{
   187→		LastMovementVector = MovementVector;
   188→	}
   189→
   190→	TArray<EWjWorldBrickMovementDirection> MovementDirs = GetNextDirections();
   191→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   192→
   193→	for(EWjWorldBrickMovementDirection Direction : MovementDirs)
   194→	{
   195→		switch (Direction)
   196→		{
   197→		case EWjWorldBrickMovementDirection::Up:
   198→			++CurrentGridPosition.Y;
   199→			break;
   200→		case EWjWorldBrickMovementDirection::Right:
   201→			++CurrentGridPosition.X;
   202→			break;
   203→		case EWjWorldBrickMovementDirection::Down:
   204→			--CurrentGridPosition.Y;
   205→			break;
   206→		case EWjWorldBrickMovementDirection::Left:
   207→			--CurrentGridPosition.X;
   208→			break;
   209→		case EWjWorldBrickMovementDirection::UpRight:
   210→			++CurrentGridPosition.X;
   211→			++CurrentGridPosition.Y;
   212→			break;
   213→		case EWjWorldBrickMovementDirection::UpLeft:
   214→			--CurrentGridPosition.X;
   215→			++CurrentGridPosition.Y;
   216→			break;
   217→		case EWjWorldBrickMovementDirection::DownRight:
   218→			++CurrentGridPosition.X;
   219→			--CurrentGridPosition.Y;
   220→			break;
   221→		case EWjWorldBrickMovementDirection::DownLeft:
   222→			--CurrentGridPosition.X;
   223→			--CurrentGridPosition.Y;
   224→			break;
   225→		}
   226→	}
   227→
   228→	EndLocation = UWjWorldBrickSpawner::CalculateBrickPosition
   229→	(
   230→		CurrentGridPosition.X,
   231→		CurrentGridPosition.Y,
   232→		BrickProperties.ColumnNum,
   233→		BrickProperties.RowNum,
   234→		BrickProperties.CenterOffset,
   235→		BrickProperties.Size
   236→	);
   237→
   238→	MovementVector = EndLocation - StartLocation;
   239→
   240→	return MovementVector;
   241→}
   242→
   243→TArray<EWjWorldBrickMovementDirection> UWjWorldBrickMovement::GetNextDirections()
   244→{
   245→	if (!BrickComponent.IsValid()) return TArray<EWjWorldBrickMovementDirection>();
   246→	if (!GameRule.IsValid()) return TArray<EWjWorldBrickMovementDirection>();
   247→
   248→	TArray<EWjWorldBrickMovementDirection> Result;
   249→	const TSet<FIntPoint>& FloodFillPoints = GameRule->GetFloodFillPoints();
   250→
   251→	struct FPointWithDirection
   252→	{
   253→		FIntPoint Point;
   254→		EWjWorldBrickMovementDirection Direction;
   255→	};
   256→
   257→	TArray<FPointWithDirection> CheckPoints = {
   258→		{ FIntPoint(CurrentGridPosition.X + 1, CurrentGridPosition.Y), EWjWorldBrickMovementDirection::Right },
   259→		{ FIntPoint(CurrentGridPosition.X - 1, CurrentGridPosition.Y), EWjWorldBrickMovementDirection::Left },
   260→		{ FIntPoint(CurrentGridPosition.X, CurrentGridPosition.Y + 1), EWjWorldBrickMovementDirection::Up },
   261→		{ FIntPoint(CurrentGridPosition.X, CurrentGridPosition.Y - 1), EWjWorldBrickMovementDirection::Down },
   262→		{ FIntPoint(CurrentGridPosition.X + 1, CurrentGridPosition.Y + 1), EWjWorldBrickMovementDirection::UpRight },
   263→		{ FIntPoint(CurrentGridPosition.X - 1, CurrentGridPosition.Y + 1), EWjWorldBrickMovementDirection::UpLeft },
   264→		{ FIntPoint(CurrentGridPosition.X + 1, CurrentGridPosition.Y - 1), EWjWorldBrickMovementDirection::DownRight },
   265→		{ FIntPoint(CurrentGridPosition.X - 1, CurrentGridPosition.Y - 1), EWjWorldBrickMovementDirection::DownLeft }
   266→	};
   267→
   268→	for (const auto& CheckPoint : CheckPoints)
   269→	{
   270→		if (FloodFillPoints.Contains(CheckPoint.Point))
   271→		{
   272→			Result.Add(CheckPoint.Direction);
   273→		}
   274→	}
   275→
   276→	return Result;
   277→}
