   279→void UWjWorldBrickMovement::PushBrick(const FVector& Direction, float InMoveAllowTime)
   280→{
   281→	if (!BrickComponent.IsValid()) return;
   282→	if (bIsMoving) return; // 이미 이동 중이면 무시
   283→
   284→	// 연쇄 밀림 체크: 밀릴 수 있는지, 밀어야 할 벽돌 목록 수집
   285→	TArray<UWjWorldBrickComponent*> BricksToMove;
   286→	bool bCanPush = CanPushInDirection(Direction, BricksToMove);
   287→
   288→	if (!bCanPush)
   289→	{
   290→		// 막혀서 밀 수 없음 -> 파괴
   291→		UE_LOG(LogWjWorld, Log, TEXT("PushBrick blocked, destroying brick at %s"), *BrickComponent->GetComponentLocation().ToString());
   292→		BrickComponent->ReserveDestroyBrick(0.0f);
   293→		return;
   294→	}
   295→
   296→	// 연쇄 밀림: 뒤에서부터 밀어야 충돌 안 함
   297→	for (int32 i = BricksToMove.Num() - 1; i >= 0; --i)
   298→	{
   299→		UWjWorldBrickComponent* BrickToMove = BricksToMove[i];
   300→		if (BrickToMove && BrickToMove != BrickComponent.Get())
   301→		{
   302→			if (UWjWorldBrickMovement* OtherMovement = BrickToMove->GetBrickMovement())
   303→			{
   304→				OtherMovement->ExecutePush(Direction, InMoveAllowTime);
   305→			}
   306→		}
   307→	}
   308→
   309→	// 자신도 밀림
   310→	ExecutePush(Direction, InMoveAllowTime);
   311→}
   312→
   313→void UWjWorldBrickMovement::ExecutePush(const FVector& Direction, float InMoveAllowTime)
   314→{
   315→	if (!BrickComponent.IsValid()) return;
   316→	if (bIsMoving) return;
   317→
   318→	bIsMoving = true;
   319→
   320→	TargetActor = BrickComponent->GetOwner();
   321→	StartLocation = BrickComponent->GetComponentLocation();
   322→
   323→	// Direction을 정규화하고 벽돌 크기만큼 이동
   324→	FVector NormalizedDir = Direction.GetSafeNormal();
   325→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   326→
   327→	// 이동 방향에 따라 적절한 거리 계산
   328→	FVector MoveDistance = FVector::ZeroVector;
   329→	if (FMath::Abs(NormalizedDir.X) > FMath::Abs(NormalizedDir.Y))
   330→	{
   331→		MoveDistance.X = FMath::Sign(NormalizedDir.X) * BrickProperties.Size.X;
   332→	}
   333→	else
   334→	{
   335→		MoveDistance.Y = FMath::Sign(NormalizedDir.Y) * BrickProperties.Size.Y;
   336→	}
   337→
   338→	EndLocation = StartLocation + MoveDistance;
   339→	MoveAllowTime = InMoveAllowTime;
   340→	MoveElapsedTime = 0.0f;
   341→	MovementVector = MoveDistance;
   342→
   343→	UE_LOG(LogWjWorld, Log, TEXT("ExecutePush: %s -> %s"), *StartLocation.ToString(), *EndLocation.ToString());
   344→}
