   346→bool UWjWorldBrickMovement::CanPushInDirection(const FVector& Direction, TArray<UWjWorldBrickComponent*>& OutBricksToMove)
   347→{
   348→	if (!BrickComponent.IsValid()) return false;
   349→
   350→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   351→	FVector CurrentCheckLocation = BrickComponent->GetComponentLocation();
   352→
   353→	// Direction을 정규화하고 벽돌 크기만큼 이동 거리 계산
   354→	FVector NormalizedDir = Direction.GetSafeNormal();
   355→	FVector MoveDistance = FVector::ZeroVector;
   356→	if (FMath::Abs(NormalizedDir.X) > FMath::Abs(NormalizedDir.Y))
   357→	{
   358→		MoveDistance.X = FMath::Sign(NormalizedDir.X) * BrickProperties.Size.X;
   359→	}
   360→	else
   361→	{
   362→		MoveDistance.Y = FMath::Sign(NormalizedDir.Y) * BrickProperties.Size.Y;
   363→	}
   364→
   365→	// 자신을 목록에 추가
   366→	OutBricksToMove.Add(BrickComponent.Get());
   367→
   368→	// 다음 위치 체크
   369→	FVector NextLocation = CurrentCheckLocation + MoveDistance;
   370→
   371→	// 최대 체크 횟수 (무한 루프 방지)
   372→	const int32 MaxChainLength = 20;
   373→	int32 ChainCount = 0;
   374→
   375→	while (ChainCount < MaxChainLength)
   376→	{
   377→		++ChainCount;
   378→
   379→		// 다음 위치가 막혀있는지 체크 (Standard 벽돌, 맵 경계 등)
   380→		if (IsLocationBlocked(NextLocation))
   381→		{
   382→			return false; // 막혀있으면 밀 수 없음
   383→		}
   384→
   385→		// 다음 위치에 Moving 타입 벽돌이 있는지 체크
   386→		UWjWorldBrickComponent* BrickAtNext = FindBrickAtLocation(NextLocation);
   387→		if (BrickAtNext)
   388→		{
   389→			if (BrickAtNext->GetBrickProperties().BrickType == EWjWorldBrickType::Moving)
   390→			{
   391→				// Moving 벽돌 발견 -> 연쇄 밀림 대상에 추가
   392→				OutBricksToMove.Add(BrickAtNext);
   393→				NextLocation = NextLocation + MoveDistance;
   394→				continue;
   395→			}
   396→			else if (BrickAtNext->GetBrickProperties().BrickType == EWjWorldBrickType::Standard)
   397→			{
   398→				// Standard 벽돌에 막힘
   399→				return false;
   400→			}
   401→			else
   402→			{
   403→				// Destructible, Explosive 등은 밀 수 있음 (해당 벽돌은 파괴됨)
   404→				break;
   405→			}
   406→		}
   407→		else
   408→		{
   409→			// 빈 공간 -> 밀 수 있음
   410→			break;
   411→		}
   412→	}
   413→
   414→	return true;
   415→}
