   417→void UWjWorldBrickMovement::CheckCollisionWithOtherBricks()
   418→{
   419→	if (!BrickComponent.IsValid()) return;
   420→	if (!TargetActor.IsValid()) return;
   421→
   422→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   423→	const FVector CurrentLocation = TargetActor->GetActorLocation();
   424→	const FVector HalfSize = BrickProperties.Size * 0.4f; // 약간 작게 체크
   425→
   426→	TArray<FOverlapResult> Overlaps;
   427→	FCollisionShape CollisionShape = FCollisionShape::MakeBox(HalfSize);
   428→
   429→	if (GetWorld()->OverlapMultiByObjectType(
   430→		Overlaps,
   431→		CurrentLocation,
   432→		FQuat::Identity,
   433→		FCollisionObjectQueryParams::AllObjects,
   434→		CollisionShape))
   435→	{
   436→		for (const FOverlapResult& Overlap : Overlaps)
   437→		{
   438→			AWjWorldBrickActor* OtherBrickActor = Cast<AWjWorldBrickActor>(Overlap.GetActor());
   439→			if (!OtherBrickActor) continue;
   440→			if (OtherBrickActor == TargetActor.Get()) continue; // 자기 자신 제외
   441→
   442→			UWjWorldBrickComponent* OtherBrickComponent = OtherBrickActor->GetBrickComponent();
   443→			if (!OtherBrickComponent) continue;
   444→
   445→			// Standard 타입이 아닌 벽돌만 충돌 처리
   446→			if (OtherBrickComponent->GetBrickProperties().BrickType != EWjWorldBrickType::Standard)
   447→			{
   448→				NotifyCollisionToBrick(OtherBrickComponent, MovementVector);
   449→			}
   450→		}
   451→	}
   452→}
   453→
   454→void UWjWorldBrickMovement::NotifyCollisionToBrick(UWjWorldBrickComponent* OtherBrick, const FVector& Direction)
   455→{
   456→	if (!OtherBrick) return;
   457→
   458→	OtherBrick->HandleWallCollision(Direction);
   459→}
