   461→UWjWorldBrickComponent* UWjWorldBrickMovement::FindBrickAtLocation(const FVector& Location)
   462→{
   463→	if (!BrickComponent.IsValid()) return nullptr;
   464→
   465→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   466→	const FVector HalfSize = BrickProperties.Size * 0.3f; // 약간 작게 체크
   467→
   468→	TArray<FOverlapResult> Overlaps;
   469→	FCollisionShape CollisionShape = FCollisionShape::MakeBox(HalfSize);
   470→
   471→	if (GetWorld()->OverlapMultiByObjectType(
   472→		Overlaps,
   473→		Location,
   474→		FQuat::Identity,
   475→		FCollisionObjectQueryParams::AllObjects,
   476→		CollisionShape))
   477→	{
   478→		for (const FOverlapResult& Overlap : Overlaps)
   479→		{
   480→			AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(Overlap.GetActor());
   481→			if (!BrickActor) continue;
   482→			if (BrickActor == BrickComponent->GetOwner()) continue; // 자기 자신 제외
   483→
   484→			UWjWorldBrickComponent* FoundBrick = BrickActor->GetBrickComponent();
   485→			if (FoundBrick)
   486→			{
   487→				return FoundBrick;
   488→			}
   489→		}
   490→	}
   491→
   492→	return nullptr;
   493→}
   494→
   495→bool UWjWorldBrickMovement::IsLocationBlocked(const FVector& Location)
   496→{
   497→	if (!BrickComponent.IsValid()) return true;
   498→	if (!GameRule.IsValid()) return true;
   499→
   500→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   501→
   502→	// 그리드 인덱스로 변환하여 SafeZone 범위 체크
   503→	FIntPoint GridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   504→		Location,
   505→		BrickProperties.ColumnNum,
   506→		BrickProperties.RowNum,
   507→		BrickProperties.CenterOffset,
   508→		BrickProperties.Size
   509→	);
   510→
   511→	// 맵 경계 체크
   512→	if (GridIndex.X < 0 || GridIndex.X >= BrickProperties.ColumnNum ||
   513→		GridIndex.Y < 0 || GridIndex.Y >= BrickProperties.RowNum)
   514→	{
   515→		return true; // 맵 밖으로 나가면 막힘
   516→	}
   517→
   518→	// 해당 위치에 Standard 벽돌이 있는지 체크
   519→	UWjWorldBrickComponent* BrickAtLocation = FindBrickAtLocation(Location);
   520→	if (BrickAtLocation && BrickAtLocation->GetBrickProperties().BrickType == EWjWorldBrickType::Standard)
   521→	{
   522→		return true; // Standard 벽돌에 막힘
   523→	}
   524→
   525→	return false;
   526→}
