    91→void UPlacementHUDWidgetAWEditor::ExecuteSave(const FString& SlotName)
    92→{
    93→	if (!bIsCurrentLayoutValid)
    94→	{
    95→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementHUDWidgetAWEditor: Cannot save invalid layout"));
    96→		return;
    97→	}
    98→
    99→	// CSV 파일 저장 경로 생성
   100→	// Content/WallLayouts/ 디렉토리에 저장
   101→	FString FileName = SlotName + TEXT(".csv");
   102→	FString SaveDirectory = FPaths::ProjectContentDir() / TEXT("WallLayouts");
   103→	FString FilePath = SaveDirectory / FileName;
   104→
   105→	// 디렉토리 생성 (없으면)
   106→	IFileManager& FileManager = IFileManager::Get();
   107→	if (!FileManager.DirectoryExists(*SaveDirectory))
   108→	{
   109→		FileManager.MakeDirectory(*SaveDirectory, true);
   110→	}
   111→
   112→	// CSV 파일로 저장
   113→	if (FWjWorldWallLayoutConverter::SaveWallLayoutToFile(CachedWallLayout, FilePath))
   114→	{
   115→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetAWEditor: Wall layout saved to %s (%dx%d)"),
   116→			*FilePath, CachedRowNum, CachedColumnNum);
   117→	}
   118→	else
   119→	{
   120→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementHUDWidgetAWEditor: Failed to save wall layout to %s"), *FilePath);
   121→	}
   122→
   123→	// 기본 저장 로직도 호출 (SaveGame 저장)
   124→	Super::ExecuteSave(SlotName);
   125→}
