   128→	{
   129→		if (Pair.Key && Pair.Key->IsHovered())
   130→		{
   131→			FString SlotName = Pair.Value;
   132→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementLoadDialogWidget: Slot selected: %s"), *SlotName);
   133→			OnLoadConfirmed.Broadcast(SlotName);
   134→			ClosePopup();
   135→			return;
   136→		}
   137→	}
   138→}
