   158→	if (PlacementComponent)
   159→	{
   160→		PlacementComponent->SaveLayoutToSlot(SlotName);
   161→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Layout saved to slot '%s'"), *SlotName);
   162→	}
   163→}
