    44→void UPlacementHUDWidgetAWEditor::OnSaveClicked()
    45→{
    46→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetAWEditor: Save clicked - validating layout"));
    47→
    48→	// 저장 전 레이아웃 변환 및 유효성 검사
    49→	FText ValidationMessage;
    50→	bIsCurrentLayoutValid = ConvertAndValidateLayout(ValidationMessage);
    51→
    52→	if (!SaveDialogClass)
    53→	{
    54→		// 다이얼로그 클래스가 없으면 기본 슬롯 이름으로 바로 저장
    55→		if (bIsCurrentLayoutValid)
    56→		{
    57→			FString DefaultSlotName = GetSaveSlotNameForContext(GetCurrentContext());
    58→			ExecuteSave(DefaultSlotName);
    59→		}
    60→		else
    61→		{
    62→			UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementHUDWidgetAWEditor: Cannot save - %s"), *ValidationMessage.ToString());
    63→		}
    64→		return;
    65→	}
    66→
    67→	// 이미 열려있으면 스킵
    68→	if (SaveDialogInstance && SaveDialogInstance->IsInViewport())
    69→	{
    70→		return;
    71→	}
    72→
    73→	// 다이얼로그 생성
    74→	SaveDialogInstance = CreateWidget<UPlacementSaveDialogWidget>(GetOwningPlayer(), SaveDialogClass);
    75→	if (SaveDialogInstance)
    76→	{
    77→		// 현재 컨텍스트의 기본 슬롯 이름 설정
    78→		FString DefaultSlotName = GetSaveSlotNameForContext(GetCurrentContext());
    79→		SaveDialogInstance->SetDefaultSlotName(DefaultSlotName);
    80→		SaveDialogInstance->SetContext(GetCurrentContext());
    81→
    82→		// 유효성 검사 결과 표시
    83→		SaveDialogInstance->SetValidationResult(bIsCurrentLayoutValid, ValidationMessage);
    84→
    85→		// 콜백 바인딩 (부모 클래스의 OnSaveConfirmed가 ExecuteSave 호출)
    86→		SaveDialogInstance->OnSaveConfirmed.AddDynamic(this, &UPlacementHUDWidgetBase::OnSaveConfirmed);
    87→		SaveDialogInstance->ShowPopup();
    88→	}
    89→}
