   127→bool UPlacementHUDWidgetAWEditor::ConvertAndValidateLayout(FText& OutMessage)
   128→{
   129→	CachedWallLayout.Empty();
   130→	CachedRowNum = 0;
   131→	CachedColumnNum = 0;
   132→	CachedCenterOffset = FVector::ZeroVector;
   133→
   134→	// PlacementComponent에서 데이터 프로바이더 가져오기
   135→	if (!PlacementComponent)
   136→	{
   137→		OutMessage = FText::FromString(TEXT("PlacementComponent가 없습니다."));
   138→		return false;
   139→	}
   140→
   141→	IWjWorldPlacementDataProvider* DataProvider = PlacementComponent->GetPlacementDataProvider();
   142→	if (!DataProvider)
   143→	{
   144→		OutMessage = FText::FromString(TEXT("배치 데이터 프로바이더가 없습니다."));
   145→		return false;
   146→	}
   147→
   148→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   149→
   150→	if (PlacedObjects.Num() == 0)
   151→	{
   152→		OutMessage = FText::FromString(TEXT("배치된 오브젝트가 없습니다."));
   153→		return false;
   154→	}
   155→
   156→	// 배치된 오브젝트들을 WallLayout으로 변환
   157→	bool bConvertSuccess = FWjWorldWallLayoutConverter::ConvertPlacedObjectsToWallLayout(
   158→		PlacedObjects,
   159→		BrickSize,
   160→		CachedWallLayout,
   161→		CachedRowNum,
   162→		CachedColumnNum,
   163→		CachedCenterOffset
   164→	);
   165→
   166→	if (!bConvertSuccess)
   167→	{
   168→		OutMessage = FText::FromString(TEXT("레이아웃 변환에 실패했습니다."));
   169→		return false;
   170→	}
   171→
   172→	// 유효성 검사 (IsWallClosed 등)
   173→	bool bIsValid = FWjWorldWallLayoutConverter::ValidateWallLayout(CachedWallLayout, OutMessage);
   174→
   175→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetAWEditor: Layout validation - Valid: %s, Message: %s"),
   176→		bIsValid ? TEXT("Yes") : TEXT("No"), *OutMessage.ToString());
   177→
   178→	return bIsValid;
   179→}
