    92→void UPlacementSaveDialogWidget::SetContext(EPlacementContext InContext)
    93→{
    94→	CurrentContext = InContext;
    95→	bContextSet = true;
    96→
    97→	// AW 컨텍스트의 경우 유효성 검사 UI 표시
    98→	bool bShowValidation = (CurrentContext == EPlacementContext::ApproachingWall);
    99→
   100→	if (ValidationText)
   101→	{
   102→		ValidationText->SetVisibility(bShowValidation ? ESlateVisibility::Visible : ESlateVisibility::Collapsed);
   103→	}
   104→	if (ValidationStatusText)
   105→	{
   106→		ValidationStatusText->SetVisibility(bShowValidation ? ESlateVisibility::Visible : ESlateVisibility::Collapsed);
   107→	}
   108→
   109→	// 타이틀 업데이트
   110→	if (TitleText)
   111→	{
   112→		FString TitleStr;
   113→		switch (CurrentContext)
   114→		{
   115→		case EPlacementContext::Lobby:
   116→			TitleStr = TEXT("로비 레이아웃 저장");
   117→			break;
   118→		case EPlacementContext::ApproachingWall:
   119→			TitleStr = TEXT("벽 레이아웃 저장");
   120→			break;
   121→		case EPlacementContext::JumpMap:
   122→			TitleStr = TEXT("점프맵 레이아웃 저장");
   123→			break;
   124→		default:
   125→			TitleStr = TEXT("레이아웃 저장");
   126→			break;
   127→		}
   128→		TitleText->SetText(FText::FromString(TitleStr));
   129→	}
   130→}
