   132→void UPlacementSaveDialogWidget::SetValidationResult(bool bIsValid, const FText& Message)
   133→{
   134→	bIsCurrentlyValid = bIsValid;
   135→	bValidationResultSet = true;
   136→	CachedValidationMessage = Message;
   137→
   138→	if (ValidationText)
   139→	{
   140→		ValidationText->SetText(Message);
   141→
   142→		// 유효하면 녹색, 아니면 빨강
   143→		FSlateColor TextColor = bIsValid
   144→			? FSlateColor(FLinearColor::Green)
   145→			: FSlateColor(FLinearColor::Red);
   146→		ValidationText->SetColorAndOpacity(TextColor);
   147→	}
   148→
   149→	if (ValidationStatusText)
   150→	{
   151→		ValidationStatusText->SetText(bIsValid
   152→			? FText::FromString(TEXT("[OK]"))
   153→			: FText::FromString(TEXT("[ERROR]")));
   154→
   155→		FSlateColor StatusColor = bIsValid
   156→			? FSlateColor(FLinearColor::Green)
   157→			: FSlateColor(FLinearColor::Red);
   158→		ValidationStatusText->SetColorAndOpacity(StatusColor);
   159→	}
   160→
   161→	// AW 컨텍스트에서 유효하지 않으면 저장 버튼 비활성화
   162→	if (ConfirmButton && CurrentContext == EPlacementContext::ApproachingWall)
   163→	{
   164→		ConfirmButton->SetIsEnabled(bIsValid);
   165→	}
   166→}
