   168→void UPlacementSaveDialogWidget::OnConfirmClicked()
   169→{
   170→	if (!SlotNameTextBox)
   171→	{
   172→		return;
   173→	}
   174→
   175→	FString SlotName = SlotNameTextBox->GetText().ToString();
   176→
   177→	// 빈 이름 검사
   178→	if (SlotName.IsEmpty())
   179→	{
   180→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementSaveDialogWidget: Slot name is empty"));
   181→		return;
   182→	}
   183→
   184→	// AW 컨텍스트에서 유효하지 않으면 저장 거부
   185→	if (CurrentContext == EPlacementContext::ApproachingWall && !bIsCurrentlyValid)
   186→	{
   187→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementSaveDialogWidget: Cannot save - validation failed"));
   188→		return;
   189→	}
   190→
   191→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementSaveDialogWidget: Confirm clicked with slot name: %s"), *SlotName);
   192→	OnSaveConfirmed.Broadcast(SlotName);
   193→	ClosePopup();
   194→}
