   437→bool UWjWorldPlacementComponent::ExportLayoutAsCSV(const FString& FileName)
   438→{
   439→	// AW 컨텍스트에서만 동작
   440→	if (CurrentContext != EPlacementContext::ApproachingWall)
   441→	{
   442→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   443→		return false;
   444→	}
   445→
   446→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   447→	if (!DataProvider)
   448→	{
   449→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   450→		return false;
   451→	}
   452→
   453→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   454→	if (PlacedObjects.Num() == 0)
   455→	{
   456→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   457→		return false;
   458→	}
   459→
   460→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   461→	const FApproachingWallGridConfig GridConfig;
   462→	const FVector& BrickSize = GridConfig.BrickSize;
   463→
   464→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   465→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   466→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   467→
   468→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   469→	{
   470→		const FVector& Location = Entry.Transform.GetLocation();
   471→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   472→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   473→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   474→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   475→	}
   476→
   477→	// 2. 그리드 크기 계산 (+1 = 위치 개수, +2 = 양쪽 1셀 패딩)
   478→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1 + 2;
   479→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1 + 2;
   480→
   481→	// 최소 크기 보장
   482→	GridColumns = FMath::Max(GridColumns, 3);
   483→	GridRows = FMath::Max(GridRows, 3);
   484→
   485→	// 그리드 원점: MinBounds에서 1칸 앞 (패딩용, 오브젝트가 인덱스 1부터 매핑)
   486→	FVector GridOrigin = MinBounds - FVector(BrickSize.X, BrickSize.Y, 0.0f);
   487→
   488→	// 3. 그리드 초기화 (-1 = Empty)
   489→	TArray<TArray<int32>> Grid;
   490→	Grid.SetNum(GridRows);
   491→	for (int32 Row = 0; Row < GridRows; ++Row)
   492→	{
   493→		Grid[Row].SetNum(GridColumns);
   494→		for (int32 Col = 0; Col < GridColumns; ++Col)
   495→		{
   496→			Grid[Row][Col] = -1;
   497→		}
   498→	}
   499→
   500→	// 4. 오브젝트를 그리드에 매핑 (RoundToInt로 CalculateBrickGridIndex와 일치)
   501→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   502→	{
   503→		const FVector& Location = Entry.Transform.GetLocation();
   504→
   505→		// 월드 좌표 → 그리드 인덱스
   506→		int32 Col = FMath::RoundToInt((Location.X - GridOrigin.X) / BrickSize.X);
   507→		int32 Row = FMath::RoundToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   508→
   509→		// 범위 체크
   510→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   511→		{
   512→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   513→			Grid[Row][Col] = BrickTypeValue;
   514→		}
   515→	}
   516→
   517→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   518→	FString CSVContent;
   519→
   520→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   521→	// CalculateBrickPosition은 CenterOffset을 그리드 중심으로 사용하므로, 그리드 중심 좌표를 저장
   522→	FVector CenterOffset;
   523→	CenterOffset.X = GridOrigin.X + (GridColumns - 1) * 0.5f * BrickSize.X;
   524→	CenterOffset.Y = GridOrigin.Y + (GridRows - 1) * 0.5f * BrickSize.Y;
   525→	CenterOffset.Z = 0.0f;
   526→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   527→		CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   528→
   529→	for (int32 Row = 0; Row < GridRows; ++Row)
   530→	{
   531→		for (int32 Col = 0; Col < GridColumns; ++Col)
   532→		{
   533→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   534→			if (Col < GridColumns - 1)
   535→			{
   536→				CSVContent += TEXT(",");
   537→			}
   538→		}
   539→		CSVContent += TEXT("\n");
   540→	}
   541→
   542→	// 6. 파일 저장
   543→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   544→
   545→	// 디렉토리 생성
   546→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   547→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   548→	{
   549→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   550→	}
   551→
   552→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   553→
   554→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   555→	{
   556→		LastExportedCSVPath = FilePath;
   557→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportLayoutAsCSV: Exported to '%s' (Grid: %dx%d)"),
   558→			*FilePath, GridColumns, GridRows);
   559→		return true;
   560→	}
   561→	else
   562→	{
   563→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: Failed to save file '%s'"), *FilePath);
   564→		return false;
   565→	}
   566→}
