   305→void UWjWorldPlacementComponent::SaveLayoutToSlot(const FString& SlotName)
   306→{
   307→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   308→	UWorld* World = GetWorld();
   309→	if (!World)
   310→	{
   311→		return;
   312→	}
   313→
   314→	ENetMode NetMode = World->GetNetMode();
   315→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   316→	{
   317→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayoutToSlot skipped (not host)"));
   318→		return;
   319→	}
   320→
   321→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   322→	if (!DataProvider)
   323→	{
   324→		return;
   325→	}
   326→
   327→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   328→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   329→	);
   330→
   331→	if (!SaveGame)
   332→	{
   333→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   334→		return;
   335→	}
   336→
   337→	// DataProvider의 배치 데이터 복사
   338→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   339→	SaveGame->SavedContext = CurrentContext;
   340→
   341→	if (UGameplayStatics::SaveGameToSlot(SaveGame, SlotName, 0))
   342→	{
   343→		LoadedSlotName = SlotName;
   344→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout saved to '%s' (%d objects)"),
   345→			*SlotName, SaveGame->PlacedObjects.Num());
   346→
   347→		// AW 컨텍스트인 경우 CSV도 함께 내보내기
   348→		if (CurrentContext == EPlacementContext::ApproachingWall)
   349→		{
   350→			ExportLayoutAsCSV(SlotName);
   351→		}
   352→		// JumpMap 컨텍스트인 경우 CSV도 함께 내보내기
   353→		else if (CurrentContext == EPlacementContext::JumpMap)
   354→		{
   355→			ExportJumpMapLayoutAsCSV(SlotName);
   356→		}
   357→	}
   358→	else
   359→	{
   360→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
   361→	}
   362→}
   363→
   364→bool UWjWorldPlacementComponent::LoadLayoutFromSlot(const FString& SlotName)
   365→{
   366→	UWorld* World = GetWorld();
   367→	if (!World)
   368→	{
   369→		return false;
   370→	}
   371→
   372→	// SaveGame 로드
   373→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   374→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   375→	);
   376→
   377→	if (!SaveGame)
   378→	{
   379→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to load layout from '%s'"), *SlotName);
   380→		return false;
   381→	}
   382→
   383→	// 컨텍스트 검증 (다른 컨텍스트의 레이아웃 로드 방지)
   384→	if (SaveGame->SavedContext != EPlacementContext::None && SaveGame->SavedContext != CurrentContext)
   385→	{
   386→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Context mismatch - slot '%s' is for '%s', current context is '%s'"),
   387→			*SlotName, *GetPlacementContextName(SaveGame->SavedContext), *GetPlacementContextName(CurrentContext));
   388→		return false;
   389→	}
   390→
   391→	// DataProvider가 있으면 데이터 설정
   392→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   393→	if (DataProvider)
   394→	{
   395→		// 일괄 설정 (RespawnAllPlacedObjects가 한 번만 호출됨)
   396→		DataProvider->SetPlacedObjects(SaveGame->PlacedObjects);
   397→	}
   398→
   399→	LoadedSlotName = SlotName;
   400→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout loaded from '%s' (%d objects)"),
   401→		*SlotName, SaveGame->PlacedObjects.Num());
   402→	return true;
   403→}
   404→
   405→TArray<FString> UWjWorldPlacementComponent::GetSavedLayoutSlots() const
   406→{
   407→	TArray<FString> SlotNames;
   408→
   409→	// SaveGame 디렉토리에서 모든 .sav 파일 검색
   410→	FString SaveDirectory = FPaths::ProjectSavedDir() / TEXT("SaveGames");
   411→
   412→	IFileManager& FileManager = IFileManager::Get();
   413→	TArray<FString> FoundFiles;
   414→	FileManager.FindFiles(FoundFiles, *SaveDirectory, TEXT("*.sav"));
   415→
   416→	for (const FString& FileName : FoundFiles)
   417→	{
   418→		// .sav 확장자 제거하여 슬롯 이름 추출
   419→		FString SlotName = FPaths::GetBaseFilename(FileName);
   420→
   421→		// SaveGame을 로드하여 컨텍스트 확인
   422→		UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   423→			UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   424→		);
